const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const a = tok.slice(2, 2 + n);
const sp = [a];
for (let k = 1; (1 << k) <= n; k++) {
  const prev = sp[k - 1], half = 1 << (k - 1), cur = [];
  for (let i = 0; i + (1 << k) <= n; i++) cur.push(Math.min(prev[i], prev[i + half]));
  sp.push(cur);
}
const out = [];
let pos = 2 + n;
for (let i = 0; i < q; i++) {
  const l = tok[pos] - 1, r = tok[pos + 1] - 1;
  pos += 2;
  const j = 31 - Math.clz32(r - l + 1);
  out.push(Math.min(sp[j][l], sp[j][r - (1 << j) + 1]));
}
console.log(out.join("\n"));

