import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        int levels = 1;
        while ((1 << levels) <= n) levels++;
        long[][] sp = new long[levels][];
        sp[0] = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            sp[0][i] = (long) in.nval;
        }
        for (int k = 1; k < levels; k++) {
            int len = n - (1 << k) + 1;
            sp[k] = new long[len];
            int half = 1 << (k - 1);
            for (int i = 0; i < len; i++) sp[k][i] = Math.min(sp[k - 1][i], sp[k - 1][i + half]);
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            in.nextToken();
            int l = (int) in.nval - 1;
            in.nextToken();
            int r = (int) in.nval - 1;
            int j = 31 - Integer.numberOfLeadingZeros(r - l + 1);
            out.append(Math.min(sp[j][l], sp[j][r - (1 << j) + 1])).append('\n');
        }
        System.out.print(out);
    }
}

