#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<vector<long long>> sp(1, vector<long long>(n));
    for (auto& x : sp[0]) scanf("%lld", &x);
    for (int k = 1; (1 << k) <= n; k++) {
        int len = n - (1 << k) + 1, half = 1 << (k - 1);
        sp.push_back(vector<long long>(len));
        for (int i = 0; i < len; i++) sp[k][i] = min(sp[k - 1][i], sp[k - 1][i + half]);
    }
    while (q--) {
        int l, r;
        scanf("%d %d", &l, &r);
        l--; r--;
        int j = 31 - __builtin_clz(r - l + 1);
        printf("%lld\n", min(sp[j][l], sp[j][r - (1 << j) + 1]));
    }
    return 0;
}
